def post_step(self, model_executed: bool) -> None:
    # When using async scheduling we can't get draft token ids in advance,
    # so we update draft token ids in the worker process and don't
    # need to update draft token ids here.
    if self.check_for_draft_tokens and not self.async_scheduling and model_executed:
        draft_token_ids = self.model_executor.take_draft_token_ids()
        if draft_token_ids is not None:
            self.scheduler.update_draft_token_ids(draft_token_ids)

@property
def max_concurrent_batches(self) -> int:
    # PP requires PP-size concurrent batches to fill the pipeline.
    # Async scheduling requires 2 concurrent batches to overlap.
    pp_size = self.parallel_config.pipeline_parallel_size
    if self.scheduler_config.async_scheduling:
        if self.use_v2_model_runner:
            return pp_size + 1
        # V1 Model Runner does not fully support async scheduling with PP.
        if pp_size <= 1:
            return 2
    return pp_size

elif self.scheduler_config.async_scheduling is None:
    # Enable async scheduling unless there is an incompatible option.
    if (
        self.model_config is not None
        and self.model_config.runner_type == "pooling"
    ):
        # The current implementation of asynchronous scheduling negatively
        # impacts performance of pooling models, so we disable by default.
        logger.debug(
            "Disabling asynchronous scheduling by default for pooling model."
        )
        self.scheduler_config.async_scheduling = False
    elif (
        self.speculative_config is not None
        and self.speculative_config.method not in get_args(EagleModelTypes)
        and self.speculative_config.method not in get_args(NgramGPUTypes)
        and self.speculative_config.method != "dspark"
    ):
        logger.warning_once(
            "Async scheduling not supported with %s-based "
            "speculative decoding and will be disabled.",
            self.speculative_config.method,
        )
        self.scheduler_config.async_scheduling = False
    elif (
        self.speculative_config is not None
        and self.speculative_config.disable_padded_drafter_batch
    ):
        logger.warning_once(
            "Async scheduling is not compatible with "
            "disable_padded_drafter_batch=True and will be disabled.",
        )
        self.scheduler_config.async_scheduling = False
    elif not executor_supports_async_sched:
        logger.warning_once(
            "Async scheduling will be disabled because it is not supported "
            "with the `%s` distributed executor backend. ",
            executor_backend,
        )
        self.scheduler_config.async_scheduling = False
    elif uses_rocm_deepep_ht_dbo:
        logger.warning_once(
            "Async scheduling is disabled for ROCm DeepEP "
            "high-throughput DBO because that combination can corrupt "
            "DP+EP generation accuracy."
        )
        self.scheduler_config.async_scheduling = False
    else:
        self.scheduler_config.async_scheduling = True

def get_scheduler_cls(self) -> type["SchedulerInterface"]:
    if self.scheduler_cls is None:
        if self.async_scheduling:
            from vllm.v1.core.sched.async_scheduler import AsyncScheduler

            return AsyncScheduler
        from vllm.v1.core.sched.scheduler import Scheduler

        return Scheduler

def _update_request_with_output(
    self, request: Request, new_token_ids: list[int], is_stale: bool = False
) -> tuple[list[int], bool]:
    status_before_update = request.status
    new_token_ids, stopped = super()._update_request_with_output(
        request, new_token_ids
    )

    # Placeholders were zeroed at preemption; a stale delivery must not
    # decrement them (it would underflow).
    if not is_stale:
        request.num_output_placeholders -= len(new_token_ids)
        assert request.num_output_placeholders >= 0

    # Cache the new tokens. Preempted requests should be skipped.
    if status_before_update == RequestStatus.RUNNING:
        self.kv_cache_manager.cache_blocks(
            request, request.num_computed_tokens - request.num_output_placeholders
        )
    return new_token_ids, stopped

if scheduled_spec_token_ids and (
    generated_token_ids or self.num_sampled_tokens_per_step == 0
):
    num_draft_tokens = len(scheduled_spec_token_ids)
    num_sampled = self.num_sampled_tokens_per_step
    num_accepted = max(len(generated_token_ids) - num_sampled, 0)
    num_rejected = num_draft_tokens - num_accepted
    # Rejections roll back num_computed_tokens (and, under async
    # scheduling, num_output_placeholders, which covers the spec
    # tokens). A stale rejection count predates the preemption
    # rollback and must not apply.
    if not output_is_stale:
        if request.num_computed_tokens > 0:
            request.num_computed_tokens -= num_rejected
        if request.num_output_placeholders > 0:
            request.num_output_placeholders -= num_rejected

else:
    valid_sampled_token_ids = []
    invalid_req_indices = discard_sampled_tokens_req_indices.tolist()
    invalid_req_indices_set = set(invalid_req_indices)

    # Cache the sampled tokens on the GPU and avoid CPU sync.
    # These will be copied into input_ids in the next step
    # when preparing inputs.
    # With spec decoding, this is done in propose_draft_token_ids().
    if self.input_batch.prev_sampled_token_ids is None:
        assert sampled_token_ids.shape[-1] == 1
        self.input_batch.prev_sampled_token_ids = sampled_token_ids
    self.input_batch.prev_req_id_to_index = {
        req_id: i
        for i, req_id in enumerate(self.input_batch.req_ids)
        if i not in invalid_req_indices_set
    }

class AsyncOutputFuture(Future):
    def __init__(self, async_output: AsyncModelRunnerOutput, single_value: bool):
        self.async_output = async_output
        self.single_value = single_value
        super().__init__()

    def result(self, timeout=None):
        if timeout is not None:
            raise RuntimeError("timeout not implemented")

        if not super().done():
            try:
                output = self.async_output.get_output()
                self.set_result(output if self.single_value else [output])
            except Exception as e:
                self.set_exception(e)
        return super().result()

def has_work(self) -> bool:
    """Returns true if the engine should be stepped."""
    return (
        self.engines_running
        or self.scheduler.has_requests()
        or bool(self.batch_queue)
    )

class InprocClient(EngineCoreClient):
    """
    InprocClient: client for in-process EngineCore. Intended
    for use in LLMEngine for V0-style add_request() and step()
        EngineCore setup in this process (no busy loop).

        * pushes EngineCoreRequest directly into the EngineCore
        * pulls EngineCoreOutputs by stepping the EngineCore
    """

    def __init__(self, *args, **kwargs):
        self.engine_core = EngineCore(*args, **kwargs)

    def get_output(self) -> EngineCoreOutputs:
        outputs, model_executed = self.engine_core.step_fn()
        self.engine_core.post_step(model_executed=model_executed)
        return outputs and outputs.get(0) or EngineCoreOutputs()
